mapper.select:
SELECT a.id AS account_id, a.user_id AS user_id, u.real_name AS real_name, u.grade AS grade, a.platform AS platform, a.account_name AS account_name, a.status AS status, (SELECT COUNT(*) FROM repo_project p WHERE p.account_id = a.id AND p.deleted = 0) AS project_count,
(SELECT COUNT(*) FROM repo_commit c INNER JOIN repo_project p2 ON p2.id = c.project_id AND p2.deleted = 0 WHERE p2.account_id = a.id AND c.deleted = 0 AND c.is_merge = 0) AS commit_count, DATE_FORMAT(a.last_sync_time, '%Y-%m-%d %H:%i:%s') AS last_sync_time, DATE_FORMAT(a.bind_time, '%Y-%m-%d %H:%i:%s') AS bind_time FROM repo_account a LEFT JOIN sys_user u ON u.id = a.user_id AND u.deleted = 0 WHERE a.deleted = 0
AND (a.account_name LIKE CONCAT('%', #{q.keyword}, '%') OR u.real_name LIKE CONCAT('%', #{q.keyword}, '%'))
AND a.platform = #{q.platform}
AND a.status = #{q.status}
AND u.grade = #{q.grade}
ORDER BY ${orderByClause} ORDER BY a.create_time DESC, a.id DESC
